{
  "title": "The Glass Diver's Passage",
  "gate_token": "V-aJ4xv3vgqCPw6rzoEL_A",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a shattered window in the ruined city wall.",
      "visual_description": "Mara stands before a cracked city gate, ink-stained coat flapping in the wind, compass in hand. The gate is half-collapsed, and old royal banners hang torn from the upper ramparts.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The glass diver arrives through a reflection in a puddle.",
      "visual_description": "A clear diving helmet rises from a murky puddle at Mara's feet; the coat reflects broken city lights. The diver steps out fully, water dripping onto the cobblestones.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers to life on a broken pillar.",
      "visual_description": "An oil lamp atop a cracked stone pillar flickers; one glowing eye appears in the flame. The lamp speaks in a low crackle.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector blocks the path through an archway.",
      "visual_description": "A man in dusty robes sleeps propped against a ledger-book pillow, stamped papers stuck to his sleeves. He snores loudly across the only archway leading deeper into the city.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "Mara consults her map while the tin fox scouts ahead.",
      "visual_description": "Mara unrolls a worn parchment map, brass compass gleaming. The tin fox darts ahead, key-wind tail spinning, blue glass eyes scanning the rubble.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver swims through a window to open a blocked gate.",
      "visual_description": "The diver presses a hand against a barred window, then steps through as if into water. On the other side, the diver reaches for a heavy iron lever inside the gatehouse.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Frightened townspeople watch from shuttered windows.",
      "visual_description": "Hooded figures peer through cracked shutters, eyes wide, as the party crosses a courtyard. The oracle lamp glows softly, casting long shadows.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Armored patrols march down a main avenue.",
      "visual_description": "A column of figures in dented plate armor clanks past a row of splintered market stalls. Their visors are lowered; they carry halberds. The team hides behind an overturned cart.",
      "characters": ["glass_diver", "mara_the_cartographer", "tim_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's flame eye narrows as it looks toward a spiraling black tower wrapped in thorny vines. Its voice hisses: 'That path is madness.'",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The party enters the cursed tower's base.",
      "visual_description": "A circular room with a single stone stair spiraling upward. Moss covers the walls, and a faint blue glow emanates from runes carved into the floor.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The tin fox triggers a hidden trap, causing a portcullis to fall.",
      "visual_description": "The fox steps on a loose flagstone; a metal portcullis crashes down, separating the group. The fox squeaks and backs away on the far side.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver swims through a mirror to rejoin the fox.",
      "visual_description": "A cracked full-length mirror leans against the wall. The diver touches its surface and steps through, emerging beside the tin fox. Dust motes swirl in the dim torchlight.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Mara finds a hidden passage behind a tapestry.",
      "visual_description": "Mara pulls aside a moth-eaten tapestry showing a faded map. A narrow stone corridor opens, leading upward. She gestures for the lamp to follow.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The group reunites in a treasure room full of false riches.",
      "visual_description": "A chamber glitters with coins and jewels, but the oracle lamp's eye casts a sickly light, revealing the treasure as painted lead and glass.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector dozes on the only exit stairs.",
      "visual_description": "The tax collector is slumped on a spiral staircase, ledger pillow under his head, papers scattered. He mutters in his sleep about tolls.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver retrieves the rescue target from a locked room.",
      "visual_description": "Through a frost-covered window, the diver sees a small figure chained to a wall. The diver places a hand on the glass, and the window turns to liquid. The diver reaches through.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The party flees across a crumbling bridge.",
      "visual_description": "A stone bridge arches over a dark chasm, its center missing several stones. Old royal banners drape the railings. The team runs across, the tin fox leading, the oracle lamp flickering.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They reach the far side as the bridge collapses behind them.",
      "visual_description": "The party stands on solid ground, looking back as the bridge falls into the chasm. Dust rises. The oracle lamp's eye dims. Mara marks the map with a final X.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    }
  ]
}

